import { declareWebsite } from "@common-practice/web/build/cloudflare";
import { deploymentSecrets } from "@common-practice/infrastructure/secrets";
import {
  CloudflareAccountId,
  CommitSha,
  DeploymentStage,
  PreviewCommentTarget,
  PullRequestStage,
} from "@common-practice/infrastructure/schemas";
import * as Alchemy from "alchemy";
import * as Cloudflare from "alchemy/Cloudflare";
import * as GitHub from "alchemy/GitHub";
import { Stack } from "alchemy/Stack";
import * as Config from "effect/Config";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Match from "effect/Match";
import * as Option from "effect/Option";
import * as Schema from "effect/Schema";

/**
 * GitHub Actions supplies the pull request number, repository and the head
 * commit (`BUILD_SHA`; `GITHUB_SHA` is the synthetic merge commit). The number
 * must match the stage, so a comment can never land on another pull request.
 */
const previewCommentTarget = Effect.fn("Website.previewCommentTarget")(function* ({
  stage,
}: Readonly<{ stage: PullRequestStage }>) {
  const github = Option.fromNullishOr(yield* GitHub.GitHubEnv);
  return yield* Option.match(github, {
    // A local plan of a pull-request stage posts nothing.
    onNone: () => Effect.succeed(Option.none<PreviewCommentTarget>()),
    onSome: (actions) =>
      Effect.gen(function* () {
        yield* Schema.decodeUnknownEffect(Schema.Literal(stage))(`pr-${actions.pr}`).pipe(
          Effect.mapError((cause) => new Config.ConfigError(cause)),
        );
        const sha = yield* Config.schema(CommitSha, "BUILD_SHA");
        const target = yield* Schema.decodeUnknownEffect(PreviewCommentTarget)({
          owner: actions.owner,
          repository: actions.repository,
          pr: actions.pr,
          sha,
        }).pipe(Effect.mapError((cause) => new Config.ConfigError(cause)));
        return Option.some(target);
      }),
  });
});

export default Alchemy.Stack(
  "common-practice",
  {
    providers: Layer.mergeAll(Cloudflare.providers(), GitHub.providers()),
    state: Cloudflare.state(),
    secrets: deploymentSecrets,
  },
  Effect.gen(function* () {
    // Check the account ID from the stack's resolved Doppler/.env settings.
    yield* Config.schema(CloudflareAccountId, "CLOUDFLARE_ACCOUNT_ID");
    const stack = yield* Stack;
    const stage = yield* Schema.decodeEffect(DeploymentStage)(stack.stage).pipe(
      Effect.mapError((cause) => new Config.ConfigError(cause)),
    );
    // Only a `pr-<number>` stage can publish a pull-request comment.
    const previewComment = yield* Match.value(stage).pipe(
      Match.when(Schema.is(PullRequestStage), (prStage) =>
        previewCommentTarget({ stage: prStage }),
      ),
      Match.orElse(() => Effect.succeed(Option.none<PreviewCommentTarget>())),
    );
    return yield* declareWebsite({ stage, previewComment });
  }),
);
import {
  CommonPracticeObservability,
  declareCommonPracticeAxiomResources,
} from "@common-practice/infrastructure/axiom/resources";
import { sharedDatasets } from "@common-practice/infrastructure/axiom/types";
import {
  requireProductionStage,
  telemetryStackProps,
} from "@common-practice/infrastructure/stacks/telemetry";
import * as Effect from "effect/Effect";

/** Common Practice owns its dashboards and ingest token; Site continues to own the datasets. */
export default CommonPracticeObservability.make(
  telemetryStackProps,
  Effect.gen(function* () {
    yield* requireProductionStage;
    const { dashboardCount } = yield* declareCommonPracticeAxiomResources(sharedDatasets);
    return { dashboardCount };
  }),
);
import {
  CommonPracticeTraceExport,
  declareCommonPracticeTraceDestination,
  declareCommonPracticeLogDestination,
} from "@common-practice/infrastructure/cloudflare/traces";
import {
  requireProductionStage,
  telemetryStackProps,
} from "@common-practice/infrastructure/stacks/telemetry";
import * as Effect from "effect/Effect";

/** Separate state keeps dashboard updates independent of Cloudflare trace permissions. */
export default CommonPracticeTraceExport.make(
  telemetryStackProps,
  Effect.gen(function* () {
    yield* requireProductionStage;
    const destination = yield* declareCommonPracticeTraceDestination();
    const logs = yield* declareCommonPracticeLogDestination();
    // Hosted Websites read this persisted name. Never output the destination's headers.
    return { destinationName: destination.name, logsDestinationName: logs.name };
  }),
);
import * as Alchemy from "alchemy";
import { commonPracticeObservabilityStackName } from "./addresses";

/** Common Practice's Axiom ingest token and dashboards (`alchemy.axiom.run.ts`). */
export class CommonPracticeObservability extends Alchemy.Stack<
  CommonPracticeObservability,
  { readonly dashboardCount: number }
>()(commonPracticeObservabilityStackName) {}
import * as Axiom from "alchemy/Axiom";
import * as Cloudflare from "alchemy/Cloudflare";
import { Stack } from "alchemy/Stack";
import * as Config from "effect/Config";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Schema from "effect/Schema";
import { productionStage } from "./addresses";
import { deploymentSecrets } from "../secrets";

/**
 * The providers and state both telemetry stacks (`common-practice-observability` and
 * `common-practice-trace-export`) run with. Both provider Layers read HttpClient from
 * StackServices (alchemy/Stack.ts), so neither depends on the other's output. This is
 * Alchemy's documented composition, and the diagnostic sees a dependency that is not one.
 */
export const telemetryStackProps = {
  // @effect-diagnostics-next-line layerMergeAllWithDependencies:off
  providers: Layer.mergeAll(Cloudflare.providers(), Axiom.providers()),
  state: Cloudflare.state(),
  secrets: deploymentSecrets,
};

/** Both telemetry stacks are production-only: the live Website depends on their resources. */
export const requireProductionStage = Effect.gen(function* () {
  const stack = yield* Stack;
  // oxlint-disable-next-line effect/no-schema-decoder-outside-ingress -- Alchemy supplies this raw CLI stage at the stack entrypoint.
  yield* Schema.decodeUnknownEffect(Schema.Literal(productionStage))(stack.stage).pipe(
    Effect.mapError((cause) => new Config.ConfigError(cause)),
  );
});
import * as Alchemy from "alchemy";
import * as Effect from "effect/Effect";
import { identity } from "effect/Function";
import * as Option from "effect/Option";
import { commonPracticeTraceExportStackName } from "./addresses";
import { StageReferenceMissing } from "./errors";

/** Common Practice's Cloudflare trace destination (`alchemy.trace.run.ts`). */
export class CommonPracticeTraceExport extends Alchemy.Stack<
  CommonPracticeTraceExport,
  { readonly destinationName: string; readonly logsDestinationName: string }
>()(commonPracticeTraceExportStackName) {}

/** Production's persisted `common-practice-trace-export` outputs, read from any stage. */
export const commonPracticeTraceExportProduction: Effect.Effect<CommonPracticeTraceExport> =
  Effect.suspend(() =>
    Option.match(Option.fromNullishOr(CommonPracticeTraceExport.stage.production), {
      onNone: () =>
        Effect.die(new StageReferenceMissing({ stack: commonPracticeTraceExportStackName })),
      onSome: identity,
    }),
  );
import * as Alchemy from "alchemy";
import * as Doppler from "alchemy/Doppler";
import * as Match from "effect/Match";

/** Native sources for every stack: .env overrides Doppler; shell settings are excluded. */
export const deploymentSecrets: readonly (
  | Doppler.DopplerSecretsProvider
  | Alchemy.Secrets.DotEnvProvider
  | Alchemy.Secrets.ProcessEnvProvider
)[] = [
  Doppler.Secrets(({ stage }) => ({
    project: "common-practice",
    config: Match.value(stage).pipe(
      Match.when("dev", () => "dev"),
      Match.when("production", () => "prd"),
      // The stack entrypoint checks the stage before declaring any resources.
      Match.orElse(() => "stg_preview"),
    ),
  })),
  Alchemy.Secrets.DotEnv(),
  Alchemy.Secrets.ProcessEnv({ disabled: true }),
];
import * as Context from "effect/Context";
import type { DeploymentStage } from "../schemas";

/** The checked stage, supplied by the stack entry point that decoded it. */
export class WebsiteStage extends Context.Service<WebsiteStage, DeploymentStage>()(
  "@common-practice/web/build/WebsiteStage",
) {}

