  3	import * as Predicate from "effect/Predicate";
  4	import * as Struct from "effect/Struct";
  5	import * as HttpServerRequest from "effect/http/HttpServerRequest";
  6	import { observeHostedRequest } from "@common-practice/infrastructure/runtime/request-observation";
  7	import { IsolateIdentity } from "@common-practice/infrastructure/runtime/isolate-identity";
  8	import type { IsolateRequest } from "@common-practice/infrastructure/runtime/isolate-identity";
  9	import type { DeploymentStage } from "@common-practice/infrastructure/schemas";
 10	import { WebsiteApi } from "./service";
 11	
 12	const responseStatus = (result: Response | { readonly response: Response }): number => {
 13	  if (Predicate.hasProperty(result, "response")) {
 14	    return result.response.status;
 15	  }
 16	  return result.status;
 17	};
 18	
 19	/** Record response-ready work without consuming or replacing TanStack's stream. */
 20	export const observeWebsiteResponse = <A extends Response | { readonly response: Response }, E, R>({
 21	  request,
 22	  stage,
 23	  isolate,
 24	  operation,
 25	}: {
 26	  readonly request: Request;
 27	  readonly stage: DeploymentStage;
 28	  readonly isolate: IsolateRequest;
 29	  readonly operation: Effect.Effect<A, E, R>;
 30	}) =>
 31	  observeHostedRequest({
 32	    request: HttpServerRequest.fromWeb(request),
 33	    stage,
 34	    isolate,
 35	    worker: "website",
 36	    operation: operation.pipe(Effect.map((result) => ({ status: responseStatus(result), result }))),
 37	  }).pipe(Effect.map(Struct.get("result")));
 38	
 39	/** Cloudflare captures Effect's console records and delivers them outside this program. */
 40	export const observeWebsiteRequest =
 41	  (request: Request) =>
 42	  <A extends Response | { readonly response: Response }, E, R>(operation: Effect.Effect<A, E, R>) =>
 43	    Effect.gen(function* () {
 44	      const api = yield* WebsiteApi;
 45	      const stage = yield* api.stage.pipe(Effect.option);
 46	      if (Option.isNone(stage) || stage.value === "dev") {
 47	        return yield* operation;
 48	      }
 49	      const identity = yield* IsolateIdentity;
 50	      const isolate = yield* identity.nextRequest;
 51	      return yield* observeWebsiteResponse({
 52	        request,
 53	        stage: stage.value,
 54	        isolate,
 55	        operation,
 56	      });
 57	    });
  1	import * as Boolean from "effect/Boolean";
  2	import * as Cause from "effect/Cause";
  3	import * as Effect from "effect/Effect";
  4	import * as Exit from "effect/Exit";
  5	import * as Option from "effect/Option";
  6	import * as Schema from "effect/Schema";
  7	import * as Headers from "effect/http/Headers";
  8	import type * as HttpServerRequest from "effect/http/HttpServerRequest";
  9	import type { DeploymentStage } from "../../schemas";
 10	import type { IsolateRequest } from "../isolate-identity";
 11	import { requestEventName, projectName } from "../../observability/names";
 12	import { classifyMethod, classifyTraffic, classifyAiBot, statusGroup } from "./classification";
 13	import { RequestObservationEvent } from "./schemas";
 14	import type { RequestSurface, RouteFamily } from "./schemas";
 15	import { RequestObservationError } from "./errors";
 16	
 17	export interface RequestObservationInput {
 18	  readonly request: HttpServerRequest.HttpServerRequest;
 19	  readonly stage: DeploymentStage;
 20	  readonly surface: RequestSurface;
 21	  readonly routeFamily: RouteFamily;
 22	  readonly isolate: IsolateRequest;
 23	  readonly worker: Option.Option<"website" | "backend">;
 24	}
 25	
 26	// Build only fixed labels, then check the complete outgoing log record.
 27	export const encodeRequestObservation = Effect.fnUntraced(function* <E>({
 28	  input,
 29	  exit,
 30	}: {
 31	  readonly input: RequestObservationInput;
 32	  readonly exit: Exit.Exit<{ readonly status: number }, E>;
 33	}) {
 34	  const userAgent = Headers.get(input.request.headers, "user-agent");
 35	  const status = Exit.match(exit, {
 36	    onFailure: () => Option.none<number>(),
 37	    onSuccess: (response) => Option.some(response.status),
 38	  });
 39	  const event: RequestObservationEvent = {
 40	    event: requestEventName,
 41	    project: projectName,
 42	    stage: input.stage,
 43	    surface: input.surface,
 44	    routeFamily: input.routeFamily,
 45	    method: classifyMethod(input.request.method),
 46	    outcome: Exit.match(exit, {
 47	      onFailure: (cause) =>
 48	        Boolean.match(Cause.hasInterrupts(cause), {
 49	          onFalse: () => "failed",
 50	          onTrue: () => "cancelled",
 51	        }),
 52	      onSuccess: () => "completed",
 53	    }),
 54	    statusGroup: statusGroup(status),
 55	    requestSeq: input.isolate.requestSeq,
 56	    trafficCategory: classifyTraffic(userAgent),
 57	    aiBot: classifyAiBot(userAgent),
 58	    ...Option.match(input.worker, {
 59	      onNone: () => ({}),
 60	      onSome: (worker) => ({ worker }),
 61	    }),
 62	  };
 63	  // Leave a key out when it has no value, so no log field is undefined.
 64	  const withIsolate = Option.match(input.isolate.isolateId, {
 65	    onNone: () => event,
 66	    onSome: (isolateId) => ({ ...event, isolateId }),
 67	  });
 68	  const complete = Option.match(status, {
 69	    onNone: () => withIsolate,
 70	    onSome: (responseStatus) => ({ ...withIsolate, status: responseStatus }),
 71	  });
 72	  return yield* Schema.encodeEffect(RequestObservationEvent)(complete).pipe(
 73	    Effect.mapError(() => new RequestObservationError({ reason: "invalid-event" })),
 74	  );
 75	});

