   136	   */
   137	  hostname?: string;
   138	}
   139	
   140	export const BunHttpServer = (serverOptions?: BunHttpServerOptions) =>
   141	  Layer.effect(
   142	    HttpServer,
   143	    Effect.gen(function* () {
   144	      const BunHttpServerPlatform = yield* Effect.promise(
   145	        () => import("@effect/platform-bun/BunHttpServer"),
   146	      );
   147	      return {
   148	        serve: (handler, options) =>
   149	          Effect.gen(function* () {
   150	            const port = yield* resolvePort(options);
   151	            const server = yield* BunHttpServerPlatform.make({
   152	              port,
   153	              hostname: serverOptions?.hostname ?? "0.0.0.0",
   154	            });
   155	            yield* server.serve(safeHttpEffect(handler));
   156	          }).pipe(Effect.orDie),
   157	      };
   158	    }),
   159	  );
   160	
   161	export interface NodeHttpServerOptions {
   162	  /**
   163	   * Address the Node HTTP server binds. Fly / Hetzner / Railway machines
   164	   * need `0.0.0.0`; omit to use that default.
   165	   * @default "0.0.0.0"
   166	   */
   167	  hostname?: string;
   168	}
   169	
   170	export const NodeHttpServer = (serverOptions?: NodeHttpServerOptions) =>
   171	  Layer.effect(
   172	    HttpServer,
   173	    Effect.gen(function* () {
   174	      const NodeHttpServerPlatform = yield* Effect.promise(
   175	        () => import("@effect/platform-node/NodeHttpServer"),
   176	      );
   177	      const NodeHttp = yield* Effect.promise(() => import("node:http"));
   178	      return {
   179	        serve: (handler, options) =>
   180	          Effect.gen(function* () {
   181	            const port = yield* resolvePort(options);
   182	            const shutdown = yield* Effect.serviceOption(ManagedHttpShutdown);
   183	            const managed = Option.getOrUndefined(shutdown);
   184	            if (managed?.isStopping()) return yield* Effect.interrupt;
   185	            const serve = Effect.gen(function* () {
   186	              const server = yield* NodeHttpServerPlatform.make(
   187	                () => {
   188	                  const server = NodeHttp.createServer();
   189	                  managed?.servers.add(server);
   190	                  server.once("close", () => managed?.servers.delete(server));
   191	                  return server;
   192	                },
   193	                {
   194	                  port,
   195	                  host: serverOptions?.hostname ?? "0.0.0.0",
   196	                  gracefulShutdownTimeout: managed?.drainTimeoutMs,
   197	                },
   198	              );
   199	              // The Node bridge masks interruption, including streaming writes.
   200	              yield* managed
