   202	                    Effect.withFiber((fiber) => {
   203	                      // Observe outside the adapter's request-scope finalization.
   204	                      managed.observeRequest(fiber);
   205	                      return Effect.interruptible(handled);
   206	                    }),
   207	                  )
   208	                : server.serve(safeHttpEffect(handler));
   209	            });
   210	            if (managed) {
   211	              const scope = yield* Scope.fork(managed.scope);
