    52	 * up front and names the selection, so a stack trace never has to be read
    53	 * to know which secrets source broke.
    54	 */
    55	export class DopplerSecretsError extends Data.TaggedError("DopplerSecretsError")<{
    56	  readonly selection: DopplerOptions;
    57	  readonly credentials: DopplerCredentials;
    58	  /** What the Doppler SDK failed with. */
    59	  readonly cause: { readonly _tag: string; readonly message: string };
    60	}> {
    61	  readonly [UserFacingError] = true;
    62	
    63	  override get message() {
    64	    const selection = describeSelection(this.selection);
    65	    switch (this.cause._tag) {
    66	      case "Unauthorized":
    67	        return this.credentials.profileName === undefined
    68	          ? "Doppler rejected the token. Check DOPPLER_TOKEN; to log in locally run `alchemy profile edit --add Doppler`."
    69	          : `Doppler credentials were rejected. ${refreshHint("Doppler", this.credentials.profileName)}`;
    70	      case "NotFound":
    71	        return `Doppler could not find ${selection}: ${this.cause.message}. Check Doppler.Secrets({ project, config }) and that the token has access to it.`;
    72	      default:
    73	        return `Doppler could not download secrets for ${selection}: ${this.cause.message}`;
    74	    }
    75	  }
    76	}
