    84	    "Doppler",
    85	  ).pipe(Effect.provide(DopplerAuth));
    86	  const { token } = yield* resolved.resolve;
    87	  const credentials: DopplerCredentials = {
    88	    token,
    89	    profileName: resolved.profileName,
    90	    method: resolved.config?.method,
    91	  };
    92	  return credentials;
    93	}).pipe(Effect.provide(CredentialsConfig));
    94	
    95	/** Download every secret of the selected project/config as a flat env map. */
    96	const downloadSecrets = Effect.fn("downloadDopplerSecrets")(function* (
    97	  options: DopplerOptions,
    98	  credentials: DopplerCredentials,
    99	) {
