   101	    project: options.project,
   102	    config: options.config,
   103	    format: "json",
   104	  }).pipe(
   105	    Retry.none,
   106	    Effect.provide(fromApiKey({ apiKey: credentials.token })),
   107	    Effect.timeout("30 seconds"),
   108	    Effect.mapError((cause) => new DopplerSecretsError({ selection: options, credentials, cause })),
   109	  );
   110	
   111	  const env: Record<string, string> = {};
   112	  for (const [key, value] of Object.entries(secrets)) {
   113	    if (value !== undefined) env[key] = value;
   114	  }
   115	  return env;
   116	});
   117	
   118	/** A `secrets` entry that loads a Doppler config. */
    58	export const stackConfigLayer = (
    59	  secrets?: StackSecrets,
    60	): Layer.Layer<never, ConfigError, StackServices> =>
    61	  secrets === undefined
    62	    ? Layer.empty
    63	    : Layer.effect(
    64	        ConfigProvider.ConfigProvider,
    65	        Effect.gen(function* () {
    66	          const overrides = yield* StackConfigOverrides;
    67	          if (overrides.envFile !== undefined) {
    68	            return yield* Effect.fail(
    69	              new ConfigError(
    70	                new ConfigProvider.SourceError({
    71	                  message: `--env-file cannot be combined with a stack that declares \`secrets\`. Add Secrets.DotEnv({ path: "${overrides.envFile}" }) to the list instead, or drop the flag.`,
    72	                }),
    73	              ),
    74	            );
    75	          }
    76	
    77	          const declared = yield* resolveSecretsOption(secrets);
    78	
    79	          // Every list ends with the shell unless the user placed (or disabled) it.
    80	          const entries = Array.isArray(declared) ? [...declared] : [declared];
    81	          const shellListed = entries.some(
    82	            (entry) => "_tag" in entry && entry._tag === "alchemy/SecretProvider::ProcessEnv",
    83	          );
    84	          if (!shellListed) entries.push(ProcessEnv());
    85	
    86	          // `ALCHEMY_PROFILE` is answered from `--profile` or the real shell,
    87	          // never from a provider. Every provider is built on a pinned view (so
    88	          // its credentials resolve against the right profile) and the stack
    89	          // gets a pinned view of the final result.
    90	          const profile =
    91	            overrides.profile ??
    92	            (yield* Effect.sync(() => process.env.ALCHEMY_PROFILE || undefined));
    93	          const pinned = ConfigProvider.fromEnv({
    94	            env: profile === undefined ? {} : { ALCHEMY_PROFILE: profile },
    95	          });
    96	          const pin = (provider: ConfigProvider.ConfigProvider) =>
    97	            ConfigProvider.make((path) =>
    98	              (path[0] === "ALCHEMY_PROFILE" ? pinned : provider).load(path),
    99	            );
   100	
   101	          const chain = entries.reduce<Layer.Layer<never, unknown, StackServices>>(
   102	            (below, entry) =>
   103	              ("layer" in entry ? entry.layer : entry).pipe(
   104	                // A reused entry must merge with this position's configuration,
   105	                // not return the result memoized at its first position.
   106	                Layer.fresh,
   107	                Layer.provide(
   108	                  ConfigProvider.layer(Effect.map(ConfigProvider.ConfigProvider, pin)).pipe(
   109	                    Layer.provide(below),
   110	                  ),
   111	                ),
   112	              ),
   113	            ConfigProvider.layer(ConfigProvider.fromEnv({ env: {} })),
   114	          );
   115	          const context = yield* Layer.build(chain).pipe(Effect.mapError(toConfigError));
   116	          return pin(Context.get(context, ConfigProvider.ConfigProvider));
   117	        }),
    15	
    16	/** A `secrets` entry that loads the process environment. */
    17	export class ProcessEnvProvider extends Data.TaggedClass("alchemy/SecretProvider::ProcessEnv")<{
    18	  readonly layer: SecretsLayer;
    19	}> {}
    20	
    21	/**
    22	 * The process environment as a secrets provider.
    23	 *
    24	 * It is implicit: every stack ends its `secrets` list with the shell, so a
    25	 * variable exported in the terminal or by CI overrides every provider. List
    26	 * it yourself to put it elsewhere, typically first so it becomes a fallback
    27	 * that a secrets manager overrides, or pass `disabled: true` to leave it out:
    28	 *
    29	 * ```ts
    30	 * secrets: [Secrets.ProcessEnv(), Doppler.Secrets({ project: "app", config: "prd" })]
    31	 * secrets: [Doppler.Secrets({ project: "app", config: "prd" }), Secrets.ProcessEnv({ disabled: true })]
    32	 * ```
    33	 */
    34	export const ProcessEnv = (options: SecretsOption<ProcessEnvOptions> = {}) =>
    35	  new ProcessEnvProvider({
    36	    layer: ConfigProvider.layerAdd(
    37	      Effect.gen(function* () {
    38	        const resolved = yield* resolveSecretsOption(options);
    39	        if (resolved.disabled) return ConfigProvider.fromEnv({ env: {} });
    40	        const environment = ConfigProvider.fromEnv({
    41	          preserveEmptyStrings: true,
    42	        });
    43	        // A shell has far too many variables to list; the count is enough.
    44	        const keys = yield* envKeys(environment);
    45	        yield* Effect.logDebug(`Loaded ${keys.length} secrets from the process environment`);
    46	        return environment;
    47	      }),
    48	      { asPrimary: true },
    49	    ),
    50	  });

