  1	import * as Axiom from "alchemy/Axiom";
  2	import * as Output from "alchemy/Output";
  3	import { retain } from "alchemy/RemovalPolicy";
  4	import * as Effect from "effect/Effect";
  5	import { commonPracticeDashboardDefinitions } from "./dashboards";
  6	import type { CommonPracticeDashboardDatasets } from "./dashboards/types";
  7	
  8	export { CommonPracticeObservability } from "../stacks/observability";
  9	
 10	/**
 11	 * Site owns the three physical datasets; Common Practice owns only its scoped token and
 12	 * dashboards. Cloudflare's export destinations use the token, so it is retained
 13	 * like the dashboards: removing the declaration or destroying this stack must not cut
 14	 * off production telemetry. A replaced token leaves its old generation in
 15	 * Axiom for deliberate revocation.
 16	 */
 17	export const declareCommonPracticeAxiomResources = Effect.fn(
 18	  "Axiom.declareCommonPracticeResources",
 19	)(function* (datasets: CommonPracticeDashboardDatasets) {
 20	  const ingest = yield* Axiom.ApiToken("CommonPracticeTelemetryIngest", {
 21	    name: "common-practice-telemetry-ingest",
 22	    description: "Ingest Common Practice Effect telemetry only; renamed 3 October 2026",
 23	    datasetCapabilities: {
 24	      [datasets.logsDataset]: { ingest: ["create"] },
 25	      [datasets.tracesDataset]: { ingest: ["create"] },
 26	      [datasets.metricsDataset]: { ingest: ["create"] },
 27	    },
 28	  }).pipe(retain());
 29	
 30	  const definitions = commonPracticeDashboardDefinitions(datasets);
 31	  yield* Effect.forEach(
 32	    definitions,
 33	    Effect.fnUntraced(function* (definition) {
 34	      yield* Axiom.Dashboard(definition.logicalId, {
 35	        // These declarations create the five Common Practice link IDs.
 36	        // The former dashboard objects are retired by the approved hard cutover.
 37	        uid: definition.uid,
 38	        // Alchemy's public Chart model is readonly while its provider input
 39	        // currently requires mutable SDK arrays. Alchemy resolves the typed
 40	        // document at plan time without changing its JSON value.
 41	        dashboard: Output.asOutput(definition.dashboard).as<Axiom.DashboardProps["dashboard"]>(),
 42	        overwrite: true,
 43	      }).pipe(retain());
 44	    }),
 45	    { concurrency: 1, discard: true },
 46	  );
 47	
 48	  return { ingest, dashboardCount: definitions.length };
 49	});
 20	
 21	// Keep the established public imports while the contracts have their own owner.
 22	export {
 23	  RequestSurface,
 24	  RouteFamily,
 25	  RequestObservationEvent,
 26	} from "./request-observation/schemas";
 27	export { classifyRouteFamily } from "./request-observation/classification";
 28	export type { RequestObservationInput } from "./request-observation/event.egress";
 29	
 30	// There is deliberately no latency metric or log field. The Workers clock only advances
 31	// across I/O, so a request that computes its response reads 0 ms, and an Effect histogram
 32	// exports 14 series per label set. Latency comes from Cloudflare's own root trace span:
 33	// startup lag before the first Effect span, handler CPU time and outbound fetch spans.
 34	// Parse the host's original absolute URL, exactly as the Worker received it.
 35	const routeFamilyOf = (request: HttpServerRequest.HttpServerRequest): RouteFamily =>
 36	  Result.match(Url.fromString(request.originalUrl), {
 37	    onFailure: () => "other",
 38	    onSuccess: (url) => classifyRouteFamily(url.pathname),
 39	  });
 40	
 41	const recordObservation = Effect.fnUntraced(
 42	  function* <E>({
 43	    input,
 44	    exit,
 45	  }: {
 46	    readonly input: RequestObservationInput;
 47	    readonly exit: Exit.Exit<{ readonly status: number }, E>;
 48	  }) {
 49	    const event = yield* encodeRequestObservation({ input, exit });
 50	    yield* Effect.logInfo(requestEventName).pipe(Effect.annotateLogs(event));
 51	  },
 52	  Effect.catchTag("RequestObservationError", () =>
 53	    Effect.logWarning(requestObservationInvalidEventName),
 54	  ),
 55	);
 56	
 57	/**
 58	 * Observe one request at the host boundary and retain only fixed route categories.
 59	 * The span carries the isolate's id, this request's sequence number and the isolate's
 60	 * age, so a trace shows whether its request was the isolate's first (a cold start).
 61	 * Alchemy's Cloudflare tracer forwards these scalar attributes to the native span.
 62	 */
 63	export const observeHostedRequest = Effect.fn(observerSpanName)(function* <
 64	  A extends { readonly status: number },
 65	  E,
 66	  R,
 67	>({
 68	  request,
 69	  stage,
 70	  isolate,
 71	  operation,
 72	  worker,
 73	}: {
 74	  readonly request: HttpServerRequest.HttpServerRequest;
 75	  readonly stage: DeploymentStage;
 76	  readonly isolate: IsolateRequest;
 77	  readonly operation: Effect.Effect<A, E, R>;
 78	  readonly worker?: "website" | "backend";
 79	}) {
 80	  const workerOption = Option.fromUndefinedOr(worker);
 81	  const resolvedWorker = Option.match(workerOption, {
 82	    onNone: (): "website" => "website",
 83	    onSome: (value) => value,
 84	  });
 85	  const routeFamily = routeFamilyOf(request);
 86	  const surface = surfaceForRouteFamily(routeFamily);
 87	  yield* Effect.annotateCurrentSpan({
 88	    [observerSpanAttribute.stage]: stage,
 89	    [observerSpanAttribute.routeFamily]: routeFamily,
 90	    [observerSpanAttribute.requestSeq]: isolate.requestSeq,
 91	    [observerSpanAttribute.ageMs]: isolate.ageMs,
 92	    [observerSpanAttribute.worker]: resolvedWorker,
 93	  });
 94	  yield* Option.match(isolate.isolateId, {
 95	    onNone: () => Effect.void,
 96	    onSome: (isolateId) => Effect.annotateCurrentSpan(observerSpanAttribute.isolateId, isolateId),
 97	  });
 98	  const input = { request, stage, surface, routeFamily, isolate, worker: workerOption };
 99	  // Record once the response is ready; its body stream is left untouched.
100	  return yield* operation.pipe(
101	    Effect.onExit((exit) => recordObservation({ input, exit })),
102	    // Carry only the checked environment label to nested Effect spans.
103	    Effect.annotateSpans({ project: projectName, stage }),
104	  );
105	});
  1	import * as Alchemy from "alchemy";
  2	import * as Doppler from "alchemy/Doppler";
  3	import * as Match from "effect/Match";
  4	
  5	/** Native sources for every stack: .env overrides Doppler; shell settings are excluded. */
  6	export const deploymentSecrets: readonly (
  7	  | Doppler.DopplerSecretsProvider
  8	  | Alchemy.Secrets.DotEnvProvider
  9	  | Alchemy.Secrets.ProcessEnvProvider
 10	)[] = [
 11	  Doppler.Secrets(({ stage }) => ({
 12	    project: "common-practice",
 13	    config: Match.value(stage).pipe(
 14	      Match.when("dev", () => "dev"),
 15	      Match.when("production", () => "prd"),
 16	      // The stack entrypoint checks the stage before declaring any resources.
 17	      Match.orElse(() => "stg_preview"),
 18	    ),
 19	  })),
 20	  Alchemy.Secrets.DotEnv(),
 21	  Alchemy.Secrets.ProcessEnv({ disabled: true }),
 22	];

