 3	// Both calculation hosts discard arbitrary messages, Causes, annotations and
 4	// span labels before log egress. This is containment, not safe tracing/export.
 5	export const CalculatorHostTelemetryLive = (host: "api" | "website") => {
 6	  const formatter = Logger.make(({ date, logLevel }) =>
 7	    Formatter.formatJson({
 8	      event: `${host}.runtime.event`,
 9	      level: logLevel,
10	      timestamp: date.toISOString(),
11	    })
12	  );
13	  const logger = Logger.withConsoleLog(formatter);
14	  const reporter = ErrorReporter.make(({ fiber }) =>
15	    logger.log({
16	      cause: Cause.empty,
