18	      fiber,
19	      logLevel: "Error",
20	      message: "Calculation host failure",
21	    })
22	  );
23	  return Layer.mergeAll(
24	    Logger.layer([logger]),
25	    ErrorReporter.layer([reporter])
26	  );
27	};

