 41	);
 42	
 43	export const websiteBuildProps = {
 44	  ...Option.none().pipe(websiteHosting),
 45	  rootDir: "apps/web",
 46	  memo: {
 47	    include: ["**/*", "../../packages/**", "../../content/**", "../api/src/**"],
 48	    lockfile: true,
 49	  },
 50	  compatibility: { date: "2026-09-22", flags: ["nodejs_compat", "enable_request_signal"] },
 51	  // Cache and request-cancellation support are independent Cloudflare settings.
 52	  cache: { enabled: true, crossVersionCache: false },
 53	  dev: { host: "127.0.0.1", port: 3210, strictPort: true },
 54	} satisfies Cloudflare.Website.ViteProps;
 55	
 56	/**
 57	 * Every hosted stage owns a Worker with native log and trace settings.
 58	 * `common-practice-trace-export` owns their shared Axiom destinations.
 59	 */
 60	const hostedProps = Effect.fn("Website.hostedProps")(function* ({
 61	  stage,
 62	  apiUrl,
 63	}: Readonly<{
 64	  stage: DeploymentStage;
 65	  apiUrl: Output.Output<ApiOrigin>;
 66	}>) {
 67	  const analytics = yield* commonPracticePostHogBindings({ stage });
 68	  const traceExport = yield* commonPracticeTraceExportProduction;
 69	  return {
 70	    ...websiteBuildProps,
 71	    // Alchemy's props resolver has no error channel. An invalid name derived
 72	    // from the checked stage must stop the native plan rather than fall back.
 73	    name: yield* Schema.decodeEffect(WorkerName)(`common-practice-${stage}`).pipe(Effect.orDie),
 74	    env: {
 75	      COMMON_PRACTICE_STAGE: stage,
 76	      COMMON_PRACTICE_API_URL: apiUrl,
 77	      COMMON_PRACTICE_WEBSITE_URL: Cloudflare.Worker.URL,
 78	      BACKEND: Backend,
 79	      ...analytics,
 80	    },
 81	    observability: {
 82	      enabled: true,
 83	      logs: {
 84	        enabled: true,
 85	        invocationLogs: true,
 86	        headSamplingRate: 1,
 87	        persist: true,
 88	        destinations: [traceExport.logsDestinationName],
 89	      },
 90	      traces: {
 91	        enabled: true,
 92	        headSamplingRate: 1,
 93	        persist: true,
 94	        destinations: [traceExport.destinationName],
 95	      },
 96	    },
 97	  };
 98	});
 99	
100	/**
101	 * Every stage declares only application bindings; Cloudflare owns telemetry delivery.
102	 */
103	type WebsiteBindings = Readonly<{
104	  COMMON_PRACTICE_STAGE: DeploymentStage;
105	  COMMON_PRACTICE_API_URL: ApiOrigin;
106	  COMMON_PRACTICE_WEBSITE_URL: typeof Cloudflare.Worker.URL;
107	  BACKEND: typeof Backend;
108	}> &
109	  Effect.Success<ReturnType<typeof commonPracticePostHogBindings>>;
110	
111	/**
112	 * Standard TanStack Website, privately connected to this stage's Effect backend.
113	 */
114	export class Website extends Cloudflare.Website.Vite<Website>()<
115	  WebsiteBindings,
116	  WebsiteStage | WebsiteZone | Context.Service.Identifier<typeof WebsiteApiAddress>
117	>(
118	  "Website",
119	  Effect.gen(function* () {
120	    const stage = yield* WebsiteStage;
121	    const apiUrl = yield* WebsiteApiAddress;
122	    return yield* Match.value(stage).pipe(
123	      Match.when("dev", () =>
124	        Effect.gen(function* () {
125	          const analytics = yield* commonPracticePostHogBindings({ stage });
126	          return {
127	            ...websiteBuildProps,
128	            name: WorkerName.make("common-practice-dev"),
129	            env: {
130	              ...analytics,
131	              COMMON_PRACTICE_STAGE: stage,
132	              COMMON_PRACTICE_API_URL: apiUrl,
133	              COMMON_PRACTICE_WEBSITE_URL: Cloudflare.Worker.URL,
134	              BACKEND: Backend,
135	            },
136	          };
137	        }),
138	      ),
139	      // Production overrides the shared stable-address policy with its custom domains.
140	      Match.when("production", () =>
141	        Effect.gen(function* () {
142	          const zone = yield* WebsiteZone;
143	          const hosted = yield* hostedProps({ stage, apiUrl });
144	          return { ...hosted, ...websiteHosting(zone) };
145	        }),
146	      ),
147	      Match.whenOr("preview", "integration", () => hostedProps({ stage, apiUrl })),
148	      Match.when(Schema.is(PullRequestStage), () => hostedProps({ stage, apiUrl })),
149	      Match.exhaustive,
150	    );
151	  }),
152	) {}
153	
154	/** Worker bindings, derived from the declaration rather than written by hand. */
155	export type WebsiteEnv = Cloudflare.InferEnv<typeof Website>;
156	
157	export const validateWebsiteOutput = Effect.fn("Website.validateOutput")(function* (
158	  input: typeof WebsiteOutputInput.Type,
159	) {
160	  return yield* Schema.decodeUnknownEffect(WebsiteOutput)(input).pipe(
161	    Effect.mapError(() => new WebsiteOutputError({ reason: "invalid-website-url" })),
162	  );
163	});
164	
165	// Native mapEffect has no error channel. Invalid provider output keeps its
166	// named validation error as the fatal cause, as the API output check does.
167	export const checkedWebsiteOutput = Output.mapEffect(
168	  (websiteUrl: typeof WebsiteOutputInput.Type.websiteUrl) =>
169	    validateWebsiteOutput({ websiteUrl }).pipe(Effect.orDie),
170	);
171	
172	/** Provider URLs become a checked origin before the browser adds a route path. */
173	export const validateApiOutput = Effect.fn("Website.validateApiOutput")(function* (
174	  input: typeof ApiOutputInput.Type,
175	) {
176	  return yield* Effect.gen(function* () {
177	    const output = yield* Schema.decodeUnknownEffect(ApiOutput)(input);
178	    const url = yield* Schema.decodeEffect(Schema.URLFromString)(output.apiUrl);
179	    const apiUrl = yield* Schema.decodeEffect(ApiOrigin)(url.origin);
180	    return { apiUrl };
181	  }).pipe(Effect.mapError(() => new ApiOutputError({ reason: "invalid-api-url" })));
182	});
183	
184	/**
185	 * Declares the Website for one checked stage. A pull-request stage run by
186	 * GitHub Actions also posts its checked Preview URL on that pull request.
187	 */
188	export const declareWebsite = Effect.fn("Website.declare")(function* ({
189	  stage,
190	  previewComment,
191	}: Readonly<{ stage: DeploymentStage; previewComment: Option.Option<PreviewCommentTarget> }>) {
192	  // Production owns the live Worker; every other stage stays destroyable.
193	  const zone = yield* Boolean.match(stage === productionStage, {
194	    onFalse: () => Effect.succeedNone,
195	    onTrue: () => declareZone().pipe(Effect.asSome),
196	  });
197	  return yield* Effect.gen(function* () {
198	    const backend = yield* Backend.pipe(retain(stage === productionStage));
199	    const api = backend.url.pipe(
200	      // Native mapEffect requires a never-error Effect. An invalid deployment
201	      // address stops planning/apply with ApiOutputError as the fatal cause.
202	      Output.mapEffect((apiUrl) => validateApiOutput({ apiUrl }).pipe(Effect.orDie)),
203	    );
204	    // A distinct native namespace creates the stage-owned Website and retires
205	    // its former Worker Preview without changing production's Website identity.
206	    const website = yield* Boolean.match(stage === "production" || stage === "dev", {
207	      onTrue: () => Website,
208	      onFalse: () => Website.pipe(Namespace.push("Preview")),
209	    }).pipe(
210	      retain(stage === productionStage),
211	      Effect.provideService(WebsiteApiAddress, api.apiUrl),
212	    );
213	    // Recheck the current validation code when native Alchemy resolves the URL.
214	    const output = website.url.pipe(checkedWebsiteOutput);
215	    yield* Option.match(previewComment, {
216	      onNone: () => Effect.void,
217	      onSome: (target) => declarePreviewComment({ target, websiteUrl: output.websiteUrl }),
218	    });
219	    return { websiteUrl: output.websiteUrl, apiUrl: api.apiUrl };
220	  }).pipe(
221	    Effect.provide(BackendLive),
222	    Effect.provideService(WebsiteStage, stage),
223	    Effect.provideService(WebsiteZone, zone),
224	  );
225	});

