 29	// A forward API tag registers before its implementation Layer finishes. The
 30	// native planner retains both address Outputs, including the binding cycle.
 31	export class TaxKitWebsite extends Website.Vite<TaxKitWebsite>()(
 32	  "TaxKitWebsite",
 33	  Effect.gen(function* () {
 34	    const api = yield* TaxKitApiWorker;
 35	    const apiOrigin = api.url.pipe(
 36	      Output.map((url) => Option.getOrNull(Option.fromNullishOr(url)))
 37	    );
 38	    return {
 39	      ...Option.match(yield* NativeProductionZone, {
 40	        onNone: () => ({}),
 41	        onSome: (zone) => ({
 42	          domain: {
 43	            name: "taxkit.dev",
 44	            redirects: ["www.taxkit.dev"],
 45	            zoneId: zone.zoneId,
 46	          },
 47	        }),
 48	      }),
 49	      compatibility: {
 50	        date: "2026-10-04",
 51	        flags: ["nodejs_compat"],
 52	      },
 53	      env: {
 54	        API_PUBLIC_ORIGIN: apiOrigin,
 55	        CALCULATOR_HOST_MODE: yield* NativeAppsHostMode,
 56	        TAXKIT_API: api,
 57	        WEBSITE_PUBLIC_ORIGIN: Worker.URL,
 58	      },
 59	      // The Website's platform records can include caller URLs independently
 60	      // of its fixed application reporter. Qualified exporters remain pending.
 61	      observability: {
 62	        enabled: false,
 63	        headSamplingRate: 0,
 64	        logs: {
 65	          enabled: false,
 66	          headSamplingRate: 0,
 67	          invocationLogs: false,
 68	          persist: false,
 69	        },
 70	        traces: { enabled: false, headSamplingRate: 0, persist: false },
 71	      },
 72	      rootDir: "apps/web",
 73	      workersDev: true,
 74	    };
 75	  })
 76	) {}
 77	
 78	const NativeApiHostLive = TaxKitApiWorker.make(
 79	  Effect.gen(function* () {
 80	    const website = yield* TaxKitWebsite;
 81	    return {
 82	      ...Option.match(yield* NativeProductionZone, {
 83	        onNone: () => ({}),
 84	        onSome: (zone) => ({
 85	          domain: { name: "api.taxkit.dev", zoneId: zone.zoneId },
 86	        }),
 87	      }),
 88	      compatibility: {
 89	        date: "2026-10-04",
 90	        flags: ["nodejs_compat"],
 91	      },
 92	      env: {
 93	        API_PUBLIC_ORIGIN: Worker.URL,
 94	        CALCULATOR_HOST_MODE: yield* NativeAppsHostMode,
 95	        WEBSITE_PUBLIC_ORIGIN: website.url.pipe(
 96	          Output.map((url) => Option.getOrNull(Option.fromNullishOr(url)))
 97	        ),
 98	      },
 99	      // The app export owns its native entry; the graph crosses the workspace
100	      // through that export rather than a relative filesystem import.
101	      main: import.meta.resolve("api/worker"),
102	      observability: ApiWorkerObservability,
103	      workersDev: true,
104	    };
105	  }),
106	  ApiWorkerNativeInit
107	);
108	
109	export const declareNativeAppsStack = Effect.gen(function* () {
110	  const stage = yield* nativeAppsStage(yield* Stage);
111	  const zone =
112	    stage === "prod"
113	      ? Option.some(
114	          yield* Zone("TaxKitProductionZone", {
115	            name: "taxkit.dev",
116	            paused: false,
117	            type: "full",
118	          }).pipe(adopt(true), retain())
119	        )
120	      : Option.none<Zone>();
121	  if (Option.isSome(zone)) {
122	    // Preserve the DNS settings independently read on 7 October. This does
123	    // not change DNSSEC, registrar, TLS, mail or verification records.
124	    yield* ZoneDnsSettings("TaxKitProductionDnsSettings", {
125	      flattenAllCnames: false,
126	      foundationDns: false,
127	      multiProvider: false,
128	      nameservers: { type: "cloudflare.standard" },
129	      nsTtl: 86_400,
130	      secondaryOverrides: false,
131	      zoneId: zone.value.zoneId,
132	      zoneMode: "standard",
133	    }).pipe(retain());
134	  }
135	  return yield* Effect.gen(function* () {
136	    const api = yield* TaxKitApiWorker;
137	    const website = yield* TaxKitWebsite;
138	    return { apiUrl: api.url, websiteUrl: website.url };
139	  }).pipe(
140	    Effect.provide(NativeApiHostLive),
141	    Effect.provideService(NativeProductionZone, zone)
142	  );
143	});
