21	/**
22	 * GitHub Actions supplies the pull request number, repository and the head
23	 * commit (`BUILD_SHA`; `GITHUB_SHA` is the synthetic merge commit). The number
24	 * must match the stage, so a comment can never land on another pull request.
25	 */
26	const previewCommentTarget = Effect.fn("Website.previewCommentTarget")(function* ({
27	  stage,
28	}: Readonly<{ stage: PullRequestStage }>) {
29	  const github = Option.fromNullishOr(yield* GitHub.GitHubEnv);
30	  return yield* Option.match(github, {
31	    // A local plan of a pull-request stage posts nothing.
32	    onNone: () => Effect.succeed(Option.none<PreviewCommentTarget>()),
33	    onSome: (actions) =>
34	      Effect.gen(function* () {
35	        yield* Schema.decodeUnknownEffect(Schema.Literal(stage))(`pr-${actions.pr}`).pipe(
36	          Effect.mapError((cause) => new Config.ConfigError(cause)),
37	        );
38	        const sha = yield* Config.schema(CommitSha, "BUILD_SHA");
39	        const target = yield* Schema.decodeUnknownEffect(PreviewCommentTarget)({
40	          owner: actions.owner,
41	          repository: actions.repository,
42	          pr: actions.pr,
43	          sha,
44	        }).pipe(Effect.mapError((cause) => new Config.ConfigError(cause)));
45	        return Option.some(target);
46	      }),
47	  });
48	});
49	
50	export default Alchemy.Stack(
51	  "common-practice",
52	  {
53	    providers: Layer.mergeAll(Cloudflare.providers(), GitHub.providers()),
54	    state: Cloudflare.state(),
55	    secrets: deploymentSecrets,
56	  },
57	  Effect.gen(function* () {
58	    // Check the account ID from the stack's resolved Doppler/.env settings.
59	    yield* Config.schema(CloudflareAccountId, "CLOUDFLARE_ACCOUNT_ID");
60	    const stack = yield* Stack;
61	    const stage = yield* Schema.decodeEffect(DeploymentStage)(stack.stage).pipe(
62	      Effect.mapError((cause) => new Config.ConfigError(cause)),
63	    );
64	    // Only a `pr-<number>` stage can publish a pull-request comment.
65	    const previewComment = yield* Match.value(stage).pipe(
66	      Match.when(Schema.is(PullRequestStage), (prStage) =>
67	        previewCommentTarget({ stage: prStage }),
68	      ),
69	      Match.orElse(() => Effect.succeed(Option.none<PreviewCommentTarget>())),
70	    );
71	    return yield* declareWebsite({ stage, previewComment });
72	  }),
73	);
