 14	  }
 15	>()("Backend") {}
 16	
 17	export default Backend.make(
 18	  Effect.gen(function* () {
 19	    // beta.81 replaces this flag in native bundles. Never read Stack at runtime.
 20	    if (globalThis.__ALCHEMY_RUNTIME__ === true) return {};
 21	    const stack = yield* Stack;
 22	    return {
 23	      main: import.meta.url,
 24	      name: "__REPO_NAME__-" + stack.stage + "-api",
 25	      workersDev: true,
 26	      dev: { host: "127.0.0.1", port: 3211, strictPort: true },
 27	      compatibility: { date: "2026-09-22", flags: ["nodejs_compat", "enable_request_signal"] },
 28	    };
 29	  }),
 30	  Effect.gen(function* () {
 31	    if ((yield* ALCHEMY_PHASE) === "plan")
 32	      return { fetch: Effect.succeed(HttpServerResponse.empty({ status: 503 })) };
 33	    const services = yield* Layer.build(ApiHandlerLive.pipe(Layer.provide(DomainLive)));
 34	    const handler = yield* ApiHandler.pipe(Effect.provideContext(services));
 35	    // ApiHandler owns native response mapping and fixed-field failure reporting.
 36	    return { fetch: handler.http };
 37	  }),
 38	);
