 32	import { DEV_RELOAD_EXIT_CODE, DevOptions } from "./DevOptions.ts";
 33	import { ConsoleLogLive } from "./GlobalLog.ts";
 34	import { selectCliServices } from "./selectCli.ts";
 35	
 36	// Interactive dev/deploy runs use the Sigil progress UI; CI, redirected output,
 37	// and other non-interactive terminals still select the append-only renderer.
 38	// `ALCHEMY_TUI` remains the explicit override in either direction.
 39	const services = Layer.mergeAll(
 40	  Layer.provideMerge(Layer.mergeAll(selectCliServices(), CliKit.CliKitInteraction), CliKit.layer()),
 41	  RpcProviderProxy.fromEnv(),
 42	  Layer.succeed(ArtifactStore, createArtifactStore()),
 43	  // Dev runs live in this exec child, not the `alchemy` CLI process, so
 44	  // without this layer they'd export no telemetry at all. No root
 45	  // `cli.dev` span though: dev remains alive across reloads, so a wrapping
 46	  // span would not end (and export) until shutdown — plan/apply spans are the
 47	  // trace roots instead.
 48	  //
 49	  // Telemetry is layered *on top of* the console logger so the OTLP logger
 50	  // merges with it. As `mergeAll` siblings the last `CurrentLoggers` wins,
 51	  // and telemetry would replace the console logger — every `Effect.log*`
 52	  // (plan, apply progress, stack outputs) silently vanished from the
 53	  // terminal whenever telemetry was enabled.
 54	  Layer.provideMerge(TelemetryLive, ConsoleLogLive),
 55	).pipe(
 56	  Layer.provideMerge(Layer.mergeAll(AlchemyContextLive, ProfileStoreLive, CredentialsStoreLive)),
 57	  Layer.provideMerge(
 58	    Layer.mergeAll(
 59	      PlatformServices,
 60	      FetchHttpClient.layer,
 61	      ConfigProvider.layer(ConfigProvider.fromEnv()),
 62	    ),
