 66	/** `alchemy dev` normally parks forever; set for single-pass runs (tests). */
 67	const devOnce = Config.String("ALCHEMY_DEV_ONCE").pipe(
 68	  Config.withDefault(""),
 69	  Effect.map((value) => value === "1" || value === "true"),
 70	);
