 72	const runDev = Effect.fn(function* (options: DevOptions) {
 73	  const target = {
 74	    entrypoint: options.main,
 75	    stage: options.stage,
 76	    profile: options.profile,
 77	    envFile: Option.getOrUndefined(options.envFile),
 78	  };
