 96	    ? applyPlan
 97	    : applyPlan.pipe(
 98	        Effect.catchCause((cause) =>
 99	          Console.error(
100	            describeFailure("apply", cause, "keeping dev alive so healthy resources keep serving"),
101	          ).pipe(Effect.as(undefined)),
102	        ),
103	      );
104	  if (result !== undefined && once) {
105	    const kit = yield* CliKit.CliKit;
106	    yield* kit.output.print(stackOutputsView(result));
107	  }
108	  return once ? undefined : yield* Effect.never;
109	});
110	
111	/**
112	 * Resolves with the files behind the next debounced change batch. The
113	 * listener detaches itself on delivery — `Effect.callback` only runs its
114	 * cleanup on interruption, so a listener left behind would fire once per
115	 * past generation on every later change.
116	 */
117	const nextChange = (watcher: {
118	  subscribe: (listener: (change: { paths: ReadonlySet<string> }) => void) => () => void;
119	}) =>
120	  Effect.callback<ReadonlySet<string>>((resume) => {
121	    const unsubscribe = watcher.subscribe(({ paths }) => {
122	      unsubscribe();
123	      resume(Effect.succeed(paths));
124	    });
125	    return Effect.sync(unsubscribe);
126	  });
127	
128	const logReload = Effect.fn(function* (paths: ReadonlySet<string>) {
129	  const path = yield* Path.Path;
130	  yield* Effect.logInfo(
131	    `Reloading stack: changed ${[...paths]
132	      .map((file) => path.relative(initialCwd, file))
133	      .join(", ")}`,
134	  );
135	});
136	
137	/**
138	 * Node: one process, many generations. The Oxc loader imports the stack graph
139	 * under a fresh namespace each time; a change to any file it loaded
140	 * interrupts the parked run (whose scope tears down the dev widget) and the
141	 * loop imports the next generation.
142	 */
143	const runNodeDevWatcher = Effect.fn(function* (options: DevOptions) {
144	  const fs = yield* FileSystem.FileSystem;
145	  const path = yield* Path.Path;
146	  // Node reports real paths for loaded files (symlinked checkouts, macOS
147	  // `/tmp`), so the project root the graph is scoped to must be real too.
148	  // Scope to the invocation directory, not the entrypoint's directory: a
149	  // config under `infra/` commonly imports application code from `src/`.
150	  const entrypoint = yield* fs.realPath(yield* resolveStackEntrypoint(options.main));
151	  const root = yield* fs.realPath(initialCwd);
152	  const nodeModules = `${path.sep}node_modules${path.sep}`;
153	  return yield* Effect.acquireRelease(
154	    Effect.sync(() =>
155	      watchImport<{ readonly default?: unknown }>(entrypoint, {
156	        parentURL: import.meta.url,
157	        shouldInvalidate: (url) => {
158	          if (!url.startsWith("file:")) return false;
159	          const file = fileURLToPath(url);
160	          const relative = path.relative(root, file);
161	          return (
162	            !file.includes(nodeModules) &&
163	            (relative === "" ||
164	              (relative !== ".." &&
165	                !relative.startsWith(`..${path.sep}`) &&
166	                !path.isAbsolute(relative)))
167	          );
168	        },
169	      }),
170	    ),
171	    (watcher) => Effect.promise(() => watcher.close()),
172	  ).pipe(
173	    Effect.flatMap((watcher) => {
174	      const generation = devKeepAlive(runDev(options)).pipe(
175	        Effect.provideService(StackModuleLoader, {
176	          import: () => watcher.import().then(({ value }) => value),
177	        }),
178	        Effect.scoped,
179	      );
180	      return Effect.forever(
181	        Effect.raceFirst(generation, nextChange(watcher)).pipe(
182	          Effect.flatMap((paths) => (paths === undefined ? Effect.void : logReload(paths))),
183	        ),
184	      );
185	    }),
186	  );
187	});
188	
189	/**
190	 * Bun: one process per generation. Bun cannot evict evaluated modules, so the
191	 * tracker only records which project files the stack graph loads; the first
192	 * change to one of them logs, lets the generation scope tear down the dev
193	 * widget, and exits with DEV_RELOAD_EXIT_CODE for the supervisor to respawn.
194	 */
195	const runBunDevWatcher = (options: DevOptions) =>
196	  Effect.acquireRelease(
197	    Effect.sync(() =>
198	      // Match Node's project-wide graph: the stack entrypoint may live in a
199	      // subdirectory while importing sibling source trees.
200	      trackBunImports({ root: initialCwd }),
201	    ),
202	    (tracker) => Effect.promise(() => tracker.close()),
203	  ).pipe(
204	    Effect.flatMap((tracker) =>
205	      Effect.raceFirst(devKeepAlive(runDev(options)).pipe(Effect.scoped), nextChange(tracker)),
206	    ),
207	    Effect.flatMap((paths) =>
208	      paths === undefined
209	        ? Effect.void
210	        : logReload(paths).pipe(
211	            Effect.andThen(
212	              Effect.sync(() => {
213	                process.exitCode = DEV_RELOAD_EXIT_CODE;
214	              }),
215	            ),
216	          ),
217	    ),
218	  );
219	
220	/**
221	 * A run that ended by itself with nothing but interruptions in its cause was
222	 * cancelled from the inside — a provider or engine race, never the user —
223	 * so it must be reported like any other failure. Ctrl+C is different: it
224	 * interrupts the fiber running this code, so `catchCause` never gets to
225	 * park it (a parked `Effect.never` is interrupted straight away too).
226	 */
227	const describeFailure = (what: string, cause: Cause.Cause<unknown>, next: string) =>
228	  Cause.hasInterruptsOnly(cause)
229	    ? `alchemy dev: ${what} was interrupted internally (a bug in a provider or the engine — please report it with the trace below); ${next}.\n${Cause.pretty(cause)}`
230	    : `alchemy dev: ${what} failed; ${next}.\n${Cause.pretty(cause)}`;
231	
232	// A mid-edit import or planning failure must keep the watch process alive so
233	// the next save can restart it. Ctrl+C still tears the run down.
234	export const devKeepAlive = <A, E, R>(effect: Effect.Effect<A, E, R>): Effect.Effect<A, E, R> =>
235	  effect.pipe(
236	    Effect.catchCause((cause) =>
237	      Console.error(
238	        describeFailure("run", cause, "waiting for the next file change to retry"),
239	      ).pipe(Effect.andThen(Effect.never)),
240	    ),
241	  );
242	
243	const makeExec = () => {
244	  const options = Schema.decodeSync(DevOptions)(JSON.parse(process.env.ALCHEMY_EXEC_OPTIONS!));
245	  return Effect.gen(function* () {
246	    yield* installShutdownFeedback;
247	    // Subscribe to the spawner's sidecar log stream BEFORE the stack runs:
248	    // this process owns the terminal renderer, so sidecar output printed
249	    // here lands in chronological order with the run's own lines instead of
250	    // racing the shared tty. No-op outside dev. The mixed tail is also teed
251	    // to log/{stage}/{timestamp}.log; per-resource output lands in
252	    // log/{stage}/{fqn…}/ via the local providers.
253	    const devLog = yield* (yield* makeDevLogOpener)(options.stage);
254	    yield* forwardSidecarLogs((entry) => devLog.writeLine(`[${entry.channel}] ${entry.line}`));
255	    // Single-pass runs park nothing. Otherwise Node reloads the stack graph in
256	    // this process; Bun exits for the supervisor to respawn (see above).
257	    return yield* (yield* devOnce)
258	      ? devKeepAlive(runDev(options))
259	      : process.versions.bun !== undefined
260	        ? runBunDevWatcher(options)

